// 後面 20 mm 層：底邊＋R100 圓弧
const PROF_A = [...FOOT_LINE, ...arcPts(200, 100, 100, TH0, 0, 60), [0, 100]];
// 前面 5 mm 層：徑向直邊 → R10 圓角 → R50 圓弧
const PROF_B = [...FOOT_LINE, R100_END, T_LINE,
  ...arcPts(FC[0], FC[1], 10, aLine, aArc, 10),
  ...arcPts(200, 100, 50, PHI, 0, 34), [0, 100]];
block += prismY(PROF_A, 10, 30);   // 先畫後層
block += prismY(PROF_B, 30, 35);   // 再畫前層，台階就出來了

for (let i = 0; i < 41; i++) {
  const u = -R + (2 * R * (i + 0.5)) / 41;        // 晶片上的第 i 條
  const wgt = Math.sqrt(1 - (u / R) ** 2);       // 圓晶片：中間寬、兩邊窄
  const xs = x + u, dh = xs - 35;
  const depth = Math.abs(dh) < 25 ? 30 - Math.sqrt(625 - dh * dh) // φ50 孔頂
              : xs < 200 ? 100 : xs <= 202 ? 85 : xs < 241.5 ? 91 : null;
  if (depth !== null) add(depth, wgt);           // 同深度的面積加起來＝波高
}

for (const ph of ["A", "B", "C"]) {        // 抬升 → 發牌 → 分層
  const R = A.recorder(P);
  fig2(P, R, PHASES[ph]);                  // 邊畫邊登記形狀
  A.settle(R, P, { states });               // 算出每一幀誰在前面
  const r = A.audit(R, P, { frames });      // 穿插、懸空、端點、前後順序
  if (A.failures(r)) failed++;
}
// ALL PHASES PASSED

// 沿著線條的法線方向推一點點雜訊，像手在抖
const r = pts.map((p, i) => {
  const [nx, ny] = normal(pts, i);
  const o = noise(i * .09, seed + boil) * wob
          + noise(i * .5,  seed + boil + 3) * wob * .35;
  return [p[0] + nx * o, p[1] + ny * o];
});
// boil = Math.floor(t * 12)：每秒換 12 次種子，線條會「呼吸」
// p：畫到哪裡為止，0 → 1 就是一筆一筆畫出來
drawPolyline(r.slice(0, r.length * p));

const span = Math.min(Math.PI / 2, speed / 24 * .9);  // 轉越快，模糊越長
for (let j = 0; j < 14; j++) {
  b.globalAlpha = 1 / (j + 1);                         // 十四張平均
  b.setTransform(1, 0, 0, 1, 0, 0);
  b.translate(cx, cy);
  b.scale(.72, 1);                                     // 先把透視的橢圓拉成圓
  b.rotate(angle - span * j / 14);                     // 轉
  b.scale(1 / .72, 1);                                 // 再壓回透視
  b.translate(-cx, -cy);
  b.drawImage(blades, 0, 0);
}
g.drawImage(fanWithoutBlades, 0, 0);                   // 底圖：沒有扇葉的電扇
g.drawImage(spinning, 0, 0);
g.drawImage(cageAndHub, 0, 0);                         // 鋼絲與輪轂在最前面

function spiral(k) {                    // k：0 在中心，1 在尾端
  const th = lerp(.96 - 5 * Math.PI, .96, k);
  const r  = lerp(40, 420, k);
  return [cx + r * Math.cos(th), cy + r * .62 * Math.sin(th)];
}
const burnt = range(0, 160 * k).map(i => spiral(i / 160));
stroke(burnt, '#ff9a3c', 38, .4);       // 外層光暈
stroke(burnt, '#ff6a1f', 10, .95);      // 引信本體
burnt.filter((_, i) => i % 23 === 0)
     .forEach(p => smoke(p, t));        // 冒煙
camera.rotate(-.3 * Math.sin(Math.PI * progress));

function glow(x, y, k, col) {
  ctx.globalCompositeOperation = 'lighter';     // 光是「加」上去的
  for (const [r, a] of [[90, .5], [260, .2], [620, .09]]) {
    // 三層：核心、光暈、環境光
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, `rgba(${col}, ${a * k})`);
    g.addColorStop(1, 'rgba(0, 0, 0, 0)');
    ctx.fillStyle = g;
    ctx.fillRect(x - r, y - r, 2 * r, 2 * r);
  }
}

// 火焰切成 3 px 高的橫條，越靠近火尖擺得越大
const sway = y => {
  const h   = (base - y) / (base - top);   // 0 在底部，1 在火尖
  const amp = 26 * Math.pow(h, 1.6);
  return amp * (.6 * Math.sin(t * 5.1 + y * .012)
              + .4 * Math.sin(t * 8.7 + 1.3 + y * .02));
};
for (let y = top; y < bottom; y += 3)
  fg.drawImage(flame, 0, y, w, 3,         // 取一條
               x + sway(y), y, w, 3);     // 偏移後放回去

const q = smooth((t - t0) / 4.5);             // 4.5 秒拉遠
const E = Math.pow(16, 1 - q);               // 放大 16 倍 → 1 倍
ctx.filter = `blur(${Math.max(0, (E - 2) * 1.6)}px)`;
ctx.drawImage(earth, A[0] - TW[0] * E, A[1] - TW[1] * E,
              w * E, h * E);
ctx.filter = 'none';
// 最後一代的畫面用柔邊遮罩收成光點
feather(lampFrame, 1 - E / 16);
